declare(strict_types=1);
function application_release_archive_safe(string $package): bool
{
    if (!class_exists('ZipArchive') || !is_file($package)) return false;
    $zip = new ZipArchive();
    if ($zip->open($package) !== true) return false;
    $totalBytes = 0;
    $safe = $zip->numFiles > 0 && $zip->numFiles <= 20000;
    for ($i = 0; $safe && $i < $zip->numFiles; $i++) {
        $stat = $zip->statIndex($i);
        $name = str_replace('\\', '/', (string)($stat['name'] ?? ''));
        if ($name === '' || str_starts_with($name, '/') || preg_match('#(^|/)\.\.(/|$)#', $name)) { $safe = false; break; }
        $totalBytes += max(0, (int)($stat['size'] ?? 0));
        if ($totalBytes > 536870912) { $safe = false; break; }
        $external = (int)($stat[' external_attributes'] ?? $stat['external_attributes'] ?? 0);
        if ((($external >> 16) & 0xF000) === 0xA000) { $safe = false; break; }
    }
    $zip->close();
    return $safe;
}
function application_release_compatibility_valid(array $manifest): bool
{
    $compatibility = is_array($manifest['compatibility'] ?? null) ? $manifest['compatibility'] : $manifest;
    $php = trim((string)($compatibility['php'] ?? $compatibility['min_php'] ?? ''));
    $database = trim((string)($compatibility['database'] ?? ''));
    $extensions = $compatibility['extensions'] ?? [];
    return $php !== '' && $database !== '' && is_array($extensions) && count(array_filter($extensions, static fn($extension): bool => trim((string)$extension) !== '')) > 0;
}
